{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A high-transfer analogue with a piperazine/aminopyrimidine kinase-inhibitor scaffold showed 77% absolute oral bioavailability in healthy volunteers in the fed state, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The same scaffold class (brigatinib) had an estimated oral bioavailability of 46% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In the fasted state, the high-transfer analogue showed 57% absolute oral bioavailability, confirming that high oral bioavailability is not food-dependent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Trametinib, a kinase inhibitor with a high transfer score, showed 72% oral bioavailability in fasted patients, supporting high F for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib, a kinase inhibitor with a piperidine/aminopyrimidine-like core, had 75% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Fasudil, a small-molecule kinase inhibitor with a basic amine, had 69% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from high-transfer analogues, especially kinase inhibitors with piperazine/piperidine and aminopyrimidine motifs, shows absolute oral bioavailability values well above 20% (46–77%). The only low-bioavailability records have zero transferability and are not applicable. This consistent experimental evidence overrides the physicochemical prior suggesting poor absorption.",
  "evidence_gaps": [
    "No direct palbociclib absolute oral bioavailability record is present in the provided evidence; prediction relies on high-transfer analogues.",
    "Low-transfer records (TFMPP, mCPP) are not applicable due to zero transferability.",
    "Physicochemical prior suggests absorption liability, but no experimental permeability or efflux data for the query are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

